sys_script_fix.script:
var mapping = { 'utcl': 'cement', 'RMC': 'URMX', 'BPD': 'GIL' };

var swapGR = new GlideRecord('x_birl3_clm_limit_swap');
swapGR.query();

while (swapGR.next()) {

    // Populate donee_segment
    if (!swapGR.donee_site.nil()) {
        var doneeGR = new GlideRecord('x_birl3_clm_customer');
        if (doneeGR.get(swapGR.getValue('donee_site'))) {
            var doneeCode = doneeGR.getValue('company_code');
            swapGR.donee_segment = mapping[doneeCode] || doneeCode;
        }
    }

    // Populate donor_segment
    if (!swapGR.donor_site.nil()) {
        var donorGR = new GlideRecord('x_birl3_clm_customer');
        if (donorGR.get(swapGR.getValue('donor_site'))) {
            var donorCode = donorGR.getValue('company_code');
            swapGR.donor_segment = mapping[donorCode] || donorCode;
        }
    }

    swapGR.autoSysFields(false); // prevents updated_on from changing
    swapGR.setWorkflow(false);   // prevents BR/Flow from firing again
    swapGR.update();
}
